{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table ras-wh.maplemonk.ras_ecommerce_report_intermediate as select cast(n.DATE as date) as DATE, n.Marketplace, n.brand, n.MRP_Sales_in_INR, n.SP_Sales_in_INR, n.ASP, n.AOV, n.Target_SP_DRR, n.Discount_Debit_in_INR as Discount_Value, n.Discount_Percent_to_MRP, n.Discount_Percent_to_Net_Sales, n.Offsite_Spends, n.Total_Marketing_Spends as Online_Marketing_Spends, n.Total_Marketing_Spends_Incl_Tax, n.Total_Investment_Marketing_Discount, n.ROI, n.MTD_Target, n.return_perc * n.SP_Sales_in_INR as Returns, n.commission_perc * n.SP_Sales_in_INR as Commissions, ndt.Total_Invoice_Value as Primary_Sales, emt.Spends_by_Secondary, emt.Primary_by_Secondary, emt.Spends_by_Primary_Revenue, emt.TOTAL_Spends_Including_GST, emt.Secondary_Sales_Including_GST as Secondary_Target, emt.Revenue_Primaries_where_applicable_including_GST as Primary_target, from ras-wh.maplemonk.Moody_Nykaa_DSR_Fact_Items n left join ( select Brand, Marketplace, PO_Status, PO_date, sum(ifnull(Total_Invoice_Value,0)) as Total_Invoice_Value, sum(ifnull(Supplied_Value,0)) as Supplied_Value, sum(ifnull(Open_PO_Quantity,0)) as Open_PO_Quantity, sum(ifnull(PO_Quantity,0)) as PO_Quantity, sum(ifnull(InTransit_Qty,0)) as InTransit_Qty from ras-wh.maplemonk.Nykaa_Dispatch_Tracker group by 1,2,3,4 qualify row_number() over (partition by po_date,marketplace,brand) = 1 ) ndt on ndt.po_date = date(n.date) and lower(ndt.marketplace) = lower(n.marketplace) and upper(ndt.brand) = upper(n.brand) left join (select brand, marketplace, month, avg(Spends_by_Secondary) as Spends_by_Secondary, avg(Primary_by_Secondary) as Primary_by_Secondary, avg(Spends_by_Primary_Revenue) as Spends_by_Primary_Revenue, avg(TOTAL_Spends_Including_GST) as TOTAL_Spends_Including_GST, avg(Secondary_Sales_Including_GST) as Secondary_Sales_Including_GST, safe_divide(avg(Revenue_Primaries_where_applicable_including_GST),DATE_DIFF(DATE_TRUNC(DATE_ADD(month, INTERVAL 1 MONTH), MONTH), DATE_TRUNC(month, MONTH), DAY)) as Revenue_Primaries_where_applicable_including_GST from maplemonk.ecommerce_marketplace_target where marketplace = \'NYKAA\' group by 1,2,3) emt on lower(emt.marketplace) = lower(n.marketplace) and upper(emt.brand) = upper(n.brand) and date_trunc(date(n.date),month) = emt.month ; create or replace table ras-wh.maplemonk.ras_ecommerce_report as with sales as( select * from ras-wh.maplemonk.ras_ecommerce_report_intermediate ) select date, brand, marketplace, \'Target\' as sale_type, Primary_target as Primary, Target_SP_DRR as Secondary, null as Discount_and_CCOGS, null as Marketing_and_Commission, null as Offsite_R_and_R, TOTAL_Spends_Including_GST as Total_Expenses_Onsite, concat(cast(cast(Spends_by_Primary_Revenue * 100 as float64) as string),\' %\') as Total_Expense_to_Primary, concat(cast(cast(Spends_by_Secondary * 100 as float64) as string),\' %\') as Total_Expense_to_Seconday from sales union all select date, brand, marketplace, \'Achievements\' as sale_type, Primary_Sales as Primary, SP_Sales_in_INR as Secondary, Discount_Value as Discount_and_CCOGS, Total_Marketing_Spends_Incl_Tax as Marketing_and_Commission, Offsite_Spends as Offsite_R_and_R, Total_Investment_Marketing_Discount as Total_Expenses_Onsite, concat(cast((safe_divide(Total_Investment_Marketing_Discount,Primary_target) * 100) as string),\' %\') as Total_Expense_to_Primary, concat(cast((safe_divide(Total_Investment_Marketing_Discount,Target_SP_DRR) * 100) as string),\' %\') as Total_Expense_to_Seconday from sales union all select date, brand, marketplace, \'Achievement %\' as sale_type, safe_divide(Primary_Sales,Primary_target) as Primary, safe_divide(SP_Sales_in_INR,Target_SP_DRR) as Secondary, safe_divide(Discount_Value,0) as Discount_and_CCOGS, safe_divide(Total_Marketing_Spends_Incl_Tax,0) as Marketing_and_Commission, safe_divide(Offsite_Spends,0) as Offsite_R_and_R, safe_divide(Total_Investment_Marketing_Discount,TOTAL_Spends_Including_GST) as Total_Expenses_Onsite, \'N/A\' as Total_Expense_to_Primary, \'N/A\' as Total_Expense_to_Seconday from sales;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
